INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('الفِيزِيَاءُ أو عِلْمُ الفِيزِيَاءِ أو الفِيزِيقَا (الإغريقية: φυσική)، وتُسَمَّى أيضًا بـ الطَبِيعِيَّاتِ أو عِلْمِ الطَبِيعَةِ، هو العلم الذي يدرس المفاهيم الأساسية مثل: الطاقة، القوة،(1) والزمان، وكل ما ينبع من هذا، مثل الكتلة، المادة وحركتها.(2) وعلى نطاق أوسع، هو التحليل العام للطبيعة، والذي يهدف إلى فهم كيف يعمل الكون. وتحاول الفيزياء أن تفهم الظواهر الطبيعية، والقوى والحركة المؤثرة في سيرها، وصياغة المعرفة في قوانين لا تفسر العمليات السالفة فقط بل التنبؤ بمسيرة العمليات الطبيعية بنماذج تقترب رويدًا رويدًا من الواقع. يُعتبر علم الفيزياء من أحد أقدم التّخصصات الأكاديمية، فقد بدأت بالبزوغ منذ العصور الوسطى، وتميّزت كعلمٍ حديثٍ في القرن السابع عشر، وباعتبار أن أحد فروعها، وهو علم الفلك، يعد من أعرق العلومِ الكونيةِ على الإطلاقِ. خلال معظم الألفي سنةِ الماضيةِ، كانت الفيزياء (علم الطبيعة) والكيمياء وعلم الأحياء وبعض فروع الرياضيات، جزءً من الفلسفة الطبيعية، ولكن خلال الثورة العلمية في القرن السابع عشر ظهرت هذه العلوم الطبيعية كمساعي بحثية فريدة في حد ذاتها. تتقاطع الفيزياء مع العديد من مجالات البحث متعددة التخصصات، مثل الفيزياء الحيوية والكيمياء الكمومية، وحدود الفيزياء التي لم تُعرَّف تعريفاً صارماً. غالبًا ما تشرح الأفكار الجديدة في الفيزياء الآليات الأساسية التي تدرسها علوم أخرى وتقترح طرقًا جديدة للبحث في التخصصات الأكاديمية مثل الرياضيات والفلسفة. تهتم الفيزياء في الوقت نفسه بدقة القياس، وابتكار طرق جديدة للقياس تزيد من دقتها؛ فهذا هو أساس التوصل إلى التفسير السليم للظواهر الطبيعية. وتقدم الفيزياء ما توصلت إليه من طرق القياس للاستخدام في جميع العلوم الطبيعية والحيوية الأخرى كالكيمياء والطب والهندسة والأحياء وغيرها. إن التقدم الحضاري والمدني يدين بشكل كبير للتقدم الباهر لعلم الفيزياء، فجميع الأجهزة التي تملأ حياتنا اليومية أساسها الفيزياء، مثل الرادار واللاسلكي والراديو والتلفزيون والهاتف المحمول والحاسوب وأجهزة التشخيص في الطب مثل أشعة إكس والتصوير بالرنين المغناطيسي والعلاج بالأشعة، والنظارات، والتلسكوبات ومسبارات المريخ والفضاء، وأفران الميكروويف، والكهرباء والترانزيستور والميكروفون، وغيرها.(3) بالإضافة إلى مفاهيم أخرى كالفضاء والزمن، ويتعامل مع خصائص كونية محسوسة يمكن قياسها مثل القوة والطاقة والكتلة والشحنة. وتعتمد الفيزياء المنهج التجريبي، أي أنها تحاول تفسير الظواهر الطبيعية والقوانين التي تحكم الكون عن طريق نظريات قابلة للاختبار. وللفيزياء مكانة متميزة في الفكر الإنساني، وكما تأثرت بأفرع المعرفة الإنسانية الأخرى؛ فقد كان لها أيضا الأثر الحاسم في بعض الحقول المعرفية والعلمية الأخرى مثل الفلسفة والرياضيات وعلم الأحياء. ولقد تجسدت أغلب التّطورات التي أحدثتها بشكل عملي في عدّة قطاعات من التقنية والطب. فعلى سبيل المثال، أدى التّقدم في فهم الكهرطيسية إلى الانتشار الواسع في استخدام الأجهزة الكهربائية مثل التلفاز والحاسوب، وكذلك تطبيقات الديناميكا الحرارية إلى التطور المذهل في مجال المحركات ووسائل النقل الحديثة، وميكانيكا الكم إلى اختراع معدات مثل المجهر الإلكتروني، كما كان لعصر الذرة -بجانب آثاره المدمرة- استعمالات هامة لتطويع الإشعاع في علاج السرطان وتشخيص الأمراض. معظم الفيزيائيين اليوم هم عادة متخصصون في مجالين متكاملين وهما الفيزياء النظرية والفيزياء التجريبية، وتهتم الأولى بصياغة النظريات باعتماد نماذج رياضية، فيما تهتم الثانية بإجراء الاختبارات على تلك النظريات، بالإضافة إلى اكتشاف ظواهر طبيعية جديدة. وبالرغم من الكم الهائل من الاكتشافات المهمّة التي حققتها الفيزياء في القرون الأربعة الماضية، إلا أن العديد من المسائل لا تزال بدون جواب إلى حد الآن، كما أن هناك مجالات نظرية وتطبيقية تشهد نشاطًا وأبحاثًا مكثّفة. == أصل التسمية == كلمة فيزياء مأخودة من اللغة الإغريقية «φυσική فيزياء» وهي مكونة من كلمتين "ἐπιστήμη epistḗmē" وتعني «معرفة الطبيعة». في البداية عرِّبت من الإغريقية إلى فيزيقا واستخدم عدد من العلماء العرب في فجر الإسلام هذا الاسم، كما استخدم بعضُهم لفظَ فيزياء سجعًا مع لفظ كيمياء. والآن لفظ فيزيقا لم يعد يستعمل وبقي لفظ فيزياء هو المستخدم، وقد عُرِّب أيضاً من علم الطبيعة إلى طبيعياء، سجعاً مع لفظ فيزياء ولفظ كيمياء. == التاريخ == === علم الفلك القديم === علم الفلك هو واحد من أقدم العلوم الطبيعية. كانت الحضارات المبكرة التي يعود تاريخها إلى ما قبل 3000 سنة قبل الميلاد، مثل السومريين والمصريين القدماء وحضارة', 'Wikipedi