INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('في دَينهِ. في الواقع، فإن تأثير ابن الهيثم للبصريات يصنف إلى جانب تأثير نيوتن الذي يحمل نفس العنوان، والذي نُشِر بعد 700 عام. كان لترجمة كتاب البصريات تأثير كبير على أوروبا. حيث ساهم في تمكن العلماء الأوروبيون لاحقًا من بناء أجهزة طورت بناء على الأجهزة التي أنشأها ابن الهيثم، كما ساهم أيضا في فهم طريقة عمل الضوء. الشيء الذي ساعد على تطوير أدوات مهمة مثل النظارات والعدسات المكبرة والالمقاريب والآلات التصوير. === تاريخ الفيزياء التقليدية === أصبحت الفيزياء علمًا منفصلاً عندما استخدم الأوروبيون الحديثون الأوائل الأساليب التجريبية والكمية لاكتشاف ما يُعتبر الآن قوانين الفيزياء. تشمل التطورات الرئيسية في هذه الفترة الاستعاضة عن نموذج مركز الأرض للنظام الشمسي بنموذج كوبرنيكوس الشمسي، والقوانين التي تحكم حركة الهيئات الكوكبية التي حددها يوهانس كيبلر بين عامي 1609 و1619، والعمل الرائد في مجال المقاريب وعلم الفلك الرصدي بواسطة غاليليو غاليلي في القرنين السادس عشر والسابع عشر، واكتشاف إسحاق نيوتن وتوحيد قوانين الحركة والجاذبية العالمية التي ستحمل اسمه. طور نيوتن أيضا حساب التفاضل والتكامل، الدراسة الرياضية للتغيير، والتي قدمت أساليب رياضية جديدة لحل المسائل الفيزيائية. نتج اكتشاف قوانين جديدة في الديناميكا الحرارية والكيمياء والكهرطيسية عن جهود بحثية أكبر خلال الثورة الصناعية مع زيادة احتياجات الطاقة. تظل القوانين التي تضم الفيزياء التقليدية مستخدمة على نطاق واسع جدًا للكائنات ذات المقاييس اليومية التي تنتقل بسرعات غير نسبية، نظرًا لأنها توفر تقريبًا وثيقًا للغاية في مثل هذه الحالات، كما أن النظريات مثل ميكانيكا الكم ونظرية النسبية تبسط إلى نظيراتها التقليدية عند هذا الحد. ومع ذلك، أدت عدم الدقة في الميكانيكا التقليدية للأجسام الصغيرة جدًا والسرعات العالية جدًا إلى تطور الفيزياء الحديثة في القرن العشرين. === تاريخ الفيزياء الحديثة === بدأت الفيزياء الحديثة في أوائل القرن العشرين بعمل ماكس بلانك في نظرية الكم ونظرية النسبية لألبرت أينشتاين. كل من هذه النظريات جاءت بسبب عدم الدقة في الميكانيكا الكلاسيكية في بعض الحالات. تنبأت الميكانيكا الكلاسيكية بسرعة متفاوتة من الضوء، والتي لا يمكن حلها بالسرعة الثابتة التي تتنبأ بها معادلات ماكسويل الكهرطيسية؛ صُحح هذا التناقض من خلال نظرية النسبية الخاصة لآينشتاين، والتي حلت محل الميكانيكا الكلاسيكية للأجسام سريعة الحركة والسماح لسرعة ثابتة من الضوء. قدمت إشعاعات الجسم الأسود مشكلة أخرى للفيزياء الكلاسيكية، والتي صُححت عندما اقترح بلانك أن إثارة مذبذبات المواد غير ممكن إلا في خطوات منفصلة تتناسب مع ترددها؛ هذا، إلى جانب التأثير الكهروضوئي ونظرية كاملة تتنبأ بمستويات الطاقة المنفصلة للمدارات الإلكترونية، أدى إلى نظرية ميكانيكا الكم التي تولت من الفيزياء الكلاسيكية بمقاييس صغيرة للغاية. سيأتي دور ميكانيكا الكم بواسطة فيرنر هايزنبرغ، إرفين شرودنغر وبول ديراك. من هذا العمل المبكر، والعمل في المجالات ذات الصلة، اُشتق النموذج القياسي لفيزياء الجسيمات. بعد اكتشاف جسيم له خصائص تتوافق مع بوزون هيجز في سيرن في عام 2012، يبدو أن جميع الجزيئات الأساسية التي تنبأ بها النموذج القياسي، وليس غيرها، موجودة؛ ومع ذلك، فإن الفيزياء خارج النموذج القياسي، مع نظريات مثل التناظر الفائق، هي مجال نشط للبحث. مجالات الرياضيات بشكل عام مهمة في هذا المجال، مثل دراسة الاحتمالات والمجموعات. == فلسفة الفيزياء == في نواح كثيرة، تنبع الفيزياء من الفلسفة اليونانية القديمة. من محاولة طاليس الأولى لتوصيف المادة، إلى ديموقريطوس، وعلم الفلك البطلمي الخاص بمركزية الأرض، وكتاب فيزياء أرسطو (كتاب مبكر عن الفيزياء، والذي حاول تحليل وتحديد الحركة من وجهة نظر فلسفية)، قدم العديد من الفلاسفة اليونانيين نظرياتهم الخاصة للطبيعة. عرفت الفيزياء بالفلسفة الطبيعية حتى أواخر القرن الثامن عشر. بحلول القرن التاسع عشر، أصبحت الفيزياء تخصصًا متميزًا عن الفلسفة والعلوم الأخرى. تعتمد الفيزياء، كما هو الحال مع بقية العلوم، على فلسفة العلوم و«طريقتها العلمية» لتعزيز معرفتنا بالعالم المادي. توظف الطريقة العلمية المنطق المسبق وكذلك المنطق الخلفي واستخدام الاستدلال البايزي لقياس صحة نظرية ما. لقد أجاب تطور الفيزياء عن العديد من أسئلة الفلاسفة الأوائل، ولكنه أثار أيضًا أسئلة جديدة. تتضمن دراسة المسائل الفلسفية المحيطة بالفيزياء، وفلسفة الفيزياء، قضايا مثل طبيعة المكان والزمان، والحتمية، والتوقعات الميتافيزيقية مثل', 'Wikipedia Arabic - فيزياء', 'F (part 3)', 'فيزياء', '[0.0