INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('التجريبية، والواقعية. كتب العديد من علماء الفيزياء عن الآثار الفلسفية لعملهم، على سبيل المثال لابلاس، الذي دافع عن الحتمية السببية، وإرفين شرودنغر، الذي كتب عن ميكانيكا الكم. كان الفيزيائي الرياضي روجر بنروز قد أطلق عليه ستيفن هوكينج، وهو رأي يناقشه بينروز في كتابه «الطريق إلى الواقع». أشار هوكينج إلى نفسه على أنه «مختزل لا يخجل» وأثار مشكلة بينروز. == المجالات الأساسية == بينما تعمل الفيزياء على تفسير القوانين الطبيعة بوجه عام تفسر كل نظرية منها مجالا محصورا. فمثلا نجد أن قوانين الميكانيكا الكلاسيكية تصف بدقة أنظمة يكون حجمها أكبر من الذرة وتكون السرعات فيها أقل بكثير عن سرعة الضوء. أما خارج تلك الحدود فنجد أن المشاهدة لا تتطابق مع الحسابات. وساهم ألبرت أينشتاين بصياغته النسبية الخاصة عام 1905 التي تبين عدم وجود مكان مطلقا أو زمن مطلق وربطت بين الاثنين فيما يسمى الزمكان للأنظمة التي تكون السرعات فيها قريبة من سرعة الضوء (300.000 كيلومتر في الثانية). ثم جاءت أعمال ماكس بلانك وإرفين شرودنغر، وفرنر هايزنبرج وأدخلت ميكانيكا الكم، وهي تصف احتمالات تفاعلات الجسيمات تحت الذرية واستطاعت أن تعطي وصفا دقيقا للطبيعة للذرة وطبيعة الجسيمات الأولية. وبعد ذلك وحدت نظرية الحقل الكمومي بين ميكانيكا الكم ونظرية النسبية الخاصة. وتصف نظرية النسبية العامة (عام 1915) الحركة في زمكان منحني وهي تصف بدقة الأنظمة الكبيرة الكتلة على مستوي النجوم والمجرات في الكون. ولم ينجح حتى الآن ربط نظرية النسبية العامة مع النظريات الأخرى، ولكن العلماء يعملون على هذا الطريق أي ربط النسبية العامة (وهي نظرية الأنظمة الكبيرة جدا) مع نظرية الكم (وهي النظرية التي تصف الأنظمة الذرية وتحت الذرية) وتوجد حاليا عدة نظريات مقترحة للجاذبية الكمومية ولكن الأمر لم يفصل بعد. === الفيزياء التقليدية === تشمل الفيزياء التقليدية الفروع والمواضيع التقليدية التي اُعترِف بها وطورت تطويراً جيدًا قبل بداية القرن العشرين (الميكانيكا التقليدية، الصوتيات، البصريات، الديناميكا الحرارية، والكهرطيسية). تهتم الميكانيكا التقليدية بالأجسام التي تعمل بواسطة القوى والأجسام المتحركة ويمكن تقسيمها إلى السكونيات (دراسة القوى على الجسم أو الهيئات التي لا تخضع لتسارع)، علم الحركة (دراسة الحركة دون النظر إلى أسبابها)، وعلم التحريك (دراسة الحركة والقوى التي تؤثر عليه)؛ يمكن أيضًا تقسيم الميكانيكا إلى ميكانيكا صلبة وميكانيكا الموائع (المعروفة معًا باسم ميكانيكا الاستمرارية)، وتشمل هذه الأخيرة فروعًا مثل الالموائع الساكنة، وهيدروديناميكا الماء، والديناميكا الهوائية، والهوائيات. الصوتيات هي دراسة كيفية إنتاج الصوت والتحكم فيه ونقله واستقباله. تشمل الفروع الحديثة المهمة للصوتيات الموجات فوق الصوتية ودراسة الموجات الصوتية عالية التردد التي تتجاوز نطاق السمع البشري؛ الصوتيات الحيوية، فيزياء المكالمات والسمع الحيوانية، والصوتيات الكهربائية، والتلاعب بالموجات الصوتية المسموعة باستخدام الإلكترونيات. علم البصريات، والذي يختص بدراسة الضوء، لا يتعلق فقط بالضوء المرئي ولكن أيضًا بالأشعة تحت الحمراء والأشعة فوق البنفسجية، والتي تظهر جميع ظواهر الضوء المرئي باستثناء الرؤية، على سبيل المثال، الانعكاس، الانكسار، التداخل، الحيود، التشتت، واستقطاب الضوء. الحرارة هي شكل من أشكال الطاقة، الطاقة الداخلية التي تمتلكها الجزيئات التي تتكون منها المادة؛ الديناميكا الحرارية تتعامل مع العلاقات بين الحرارة وغيرها من أشكال الطاقة. تمت دراسة الكهرباء والمغناطيسية كفرع واحد للفيزياء منذ اكتشاف العلاقة الوطيدة بينهما في أوائل القرن التاسع عشر؛ ينتج عن التيار الكهربائي مجال مغناطيسي، ويحدث المجال المغناطيسي المتغير تيارًا كهربائيًا. تتعامل الإلكتروستاتيات مع الشحنات الكهربية أثناء السكون، والديناميكا الكهربائية ذات الشحنات المتحركة، والكهرباء المغناطيسية مع الأقطاب المغناطيسية الباقي. ==== الميكانيكا التقليدية ==== تصف الميكانيكا التقليدية القوى التي تؤثر على حالة الأجسام المادية وحركتها. وغالبا ما يشار إليها باسم «المِيكانيكا النيُوتُنية» نسبة إلى إسحاق نيوتن وقوانينه في الحركة. تتفرع الميكانيكا التقليدية إلى؛ السكونيات أو «الإستاتيكا» وهو يصف الأجسام ساكنة وشروط توازنها، وعلم الحركة أو «الكينماتيكا» وهو يهتم بوصف حركة الأجسام دون النظر إلى مسبباتها، وعلم التحريك أو «الديناميكا» الذي يدرس حركة الأجسام وماهية القوى المسببة لها. تقوم الميكانيكا التقليدية بشكل أولي على افتراض أن الجسم المادي المراد دراسته يكون صلبًا وفي شكل نقطة (أي أن الأبعاد بين النقاط المكونة للجسم لا تتغير مع الزمن). وتتولى على', 'Wikipedia Arabic - فيزياء', 'F (part 4)', 'فيزياء', '[0.0374146,0.0725708,0.0480042,0.0265808,0.0290375,0.0455322,0.0054398,0.0160217,-0.0142059,-0.0057259,-0.0019341,0.0452271,-0.0263519,-0.0166321,-0.0034904,0.0371704,-0.0023785,-0.0025654,0.0214691,-0.0264435,0.0567322,-0.0499573,-0.0255585,0.0254517,0.0204773,-0.0466919,-0.0212860,0.0171661,-0.0164032,0.0001609,0.0514832,-0.0208130,-0.0213470,-0.0286713,-0.0286102,0.0444641,-0.0432739,0.0014639,0.0048294,0.0211639,0.0136108,-0.0324097,-0.0515747,-0.0005574,-0.0445251,0.0545044,-0.0276337,0.0066452,0.0411987,0.0122681,0.0060387,-0.0241852,0.0529480,0.0032139,-0.0476379,0.0341492,0.0101242,-0.0021248,-0.0108795,-0.0231934,-0.0143585,-0.0175476,0.0129013,0.0180817,-0.0259857,-0.0273132,-0.0233765,-0.0114975,-0.0398865,0.0348816,0.0034542,-0.0238190,-0.0573120,0.0258026,-0.0323792,-0.0227203,0.0534363,0.0111618,0.0014381,-0.0147095,-0.0408630,-0.0097733,0.0147552,-0.0060768,0.0199738,0.0524597,0.0272827,-0.0189362,-0.0258942,-0.0296631,-0.0108261,-0.0091934,-0.0262451,0.0078506,0.0094910,-0.0056038,-0.0064468,-0.0648804,0.0009027,-0.0291595,-0.0033226,0.0340271,-0.0137482,0.0443726,0.0247345,-0.0354004,-0.0335388,-0.0160217,-0.0668335,0.0015106,0.0276947,-0.0288086,0.0240936,-0.0590210,-0.0167694,-0.0384827,-0.0322876,-0.0076790,0.0008359,-0.0261688,-0.0167999,0.0059280,0.0386353,0.0117874,0.0371399,-0.0551147,-0.0004504,0.0643311,-0.0490417,-0.0069160,-0.0186157,-0.0011778,0.0084381,-0.0321960,0.0015249,-0.0012417,0.0683594,0.0137100,0.0104599,0.0770874,0.0134964,-0.0137711,0.0325928,0.0453186,0.0314331,-0.0101166,0.0711060,0.0082703,0.0427551,0.0685425,0.0561523,0.0153732,0.0150833,0.0225220,0.0064354,-0.0247498,0.0021248,0.0517273,-0.0350342,-0.0102997,0.0336304,-0.0371094,0.0018559,-0.0297852,-0.0067291,0.0208435,-0.0407104,0.0312347,-0.0205536,-0.0185089,-0.0106506,-0.0240326,0.0279236,-0.0019436,0.0038643,-0.0204010,-0.0062180,-0.0597839,-0.0139771,-0.0094452,