INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('صعيد آخر، الميكانيكا الاستمرارية وصف المادة المتصلة والمستمرة مثل الأجسام الصلبة والسائلة والغازية، وهي تنقسم بدورها إلى قسمين؛ ميكانيكا المواد الصلبة وميكانيكا الموائع. وتدرس ميكانيكا المواد الصلبة سلوك هذه الأجسام أمام عوامل عديدة مثل الضغط وتغير درجة الحرارة والتذبذب، وغيرها. فيما تدرس ميكانيكا الموائع فيزيائية السوائل والغازات، وهي تتناول مواضيع كثيرة منها توازن السوائل في علم سكون الموائع، وتدفقها في جريان الموائع، وحركة الغازات وانتشارها إلى جانب تأثيرها على السطوح والأجسام المتحركة في الديناميكا الهوائية. أحد المفاهيم الهامة في الميكانيكا التقليدية هي مبادئ حفظ زخم الحركة والطاقة، وقد دفع هذا الأمر إلى إعادة الصياغة الرياضية لقوانين نيوتن للحركة في ميكانيكا لاجرانج وميكانيكا هاملتون باعتماد هذه المبدئ. وتقف الصياغتان الميكانيكية في وصف سلوك الأجسام على نفس المقدار من الدقة، ولكن بطريقة مستقلة عن منظومة القوى المسلطة عليها والتي تكون بعض الأحيان غير عملية في تشكيل معادلات الحركة. تعطينا الميكانيكا التقليدية نتائج وتنبوات رقمية ذات دقة عالية، تتماشى مع المشاهدة، وذلك بنسبة لأنظمة ذات أبعاد عادية وضمن مجال سرعات تقل بكثير عن سرعة الضوء. أما عندما تكون الأجسام موضع الدراسة جسيمات أولية أو أن سرعتها عالية، تكاد تقارب من سرعة الضوء، فهنا تحل محل الميكانيكا التقليدية تباعا الميكانيكا الكمومية والميكانيكا النسبية. ومع ذلك تجد الميكانيكا التقليدية مجالا لتطبيقها في وصف سلوك أنظمة دقيقة، فعلى سبيل المثال في النظرية الحركية للغازات وضغط الغاز تسري القوانين التي تحكم حركة أجسام ذات حجم العادي على الجزيئات المكونة للغازات وهو ما يُمَكن من استنتاج خصائص عيانية مثل درجة الحرارة والضغط والحجم. وفي أنظمة عالية التعقيد يمكن فيها لتغييرات طفيفة أن تنتج آثارًا كبيرة (مثل الغلاف الجوي أو مسألة الأجسام الثلاثة) تصير قدرة معادلات الميكانيكا التقليدية على التنبئ محدودة. وتختص بدراسة هذه الأنظمة، التي توصف بأنها لاخطية، نظرية الشواش. أوجدت قوانين الميكانيكا التقليدية نظرة موحدة وشاملة لظواهر طبيعية قد تبدو ظاهريًا غير متصلة، مثل وقوع تفاحة من غصن شجرة أو دوران القمر حول الأرض. فعلى سبيل المثال؛ قوانين كيبلر لحركة الكواكب، أو السرعة التي يجب أن يبلغها صاروخ للتحرر من حقل الجاذبية الأرضية (سرعة الإفلات)، يمكن استنتاجهما رياضيًا من قانون نيوتن العام للجاذبية. وقد ساهمت هذه الفكرة ومفادها أن التوصل لقوانين كليّة يمكنها وصف الظواهر الكونية على اختلافها أمر ممكن، إلى بروز الميكانيكا التقليدية عنصراً هاماً في الثورة العلمية وذلك خلال القرنين السابع والثامن عشر. ===== قوانين نيوتن في الحركة ===== تعد قوانين نيوتن في الحركة أحد أهم قوانين وأساس الميكانيكا التقليدية، وهي عبارة عن ثلاثة قوانين وتربط هذه القوانين القوى المؤثرة على الجسم وحركته. وضعها إسحاق نيوتن ليصف حركة الأجسام والعديد من الظواهر الفيزيائية. يصف قانون نيوتن الأول على أنه إذا كانت القوة المحصلة (المجموع الاتجاهي للقوى المؤثرة على الجسم) تساوي صفر، فإن سرعة الجسم تكون ثابتة. تعتبر السرعة كمية متجهة يُعبَّر عنها بمقدار هو سرعة الجسم واتجاه هو اتجاه حركة الجسم. عندما نقول أن سرعة الجسم ثابتة فإننا نعني أن كلا من المقدار والاتجاه ثابتين. ويمكن وصفه رياضيا: ∑ F = 0 ⇔', 'Wikipedia Arabic - فيزياء', 'F (part 5)', 'فيزياء', '[0.0451050,0.0528259,0.0321350,0.0028400,0.0103989,0.0367737,-0.0145950,-0.0020943,-0.0134583,0.0039673,-0.0068092,0.0465393,-0.0511475,-0.0003786,0.0062866,0.0082932,-0.0003541,0.0081635,0.0518188,-0.0145187,0.0273285,-0.0456848,0.0120850,0.0110779,0.0002161,-0.0247955,0.0019970,0.0312805,-0.0071564,0.0230560,0.0543823,-0.0182953,-0.0195312,-0.0301666,-0.0303802,0.0232086,-0.0364990,0.0008993,0.0094986,0.0086136,-0.0295105,-0.0289459,-0.0617065,0.0282135,-0.0495911,0.0249329,-0.0164490,-0.0108566,0.0137634,0.0210571,-0.0275269,-0.0125809,0.0254211,0.0367432,-0.0210419,0.0074463,0.0082703,0.0087204,0.0263367,-0.0232086,-0.0219879,-0.0598450,0.0001534,-0.0032005,-0.0086212,-0.0451355,0.0020733,0.0011673,-0.0234528,0.0440063,-0.0042877,0.0124741,-0.0492859,0.0436401,-0.0199432,-0.0144196,0.0210571,0.0188446,0.0307159,0.0052681,-0.0478516,-0.0235596,0.0329895,-0.0186615,-0.0152359,0.0231171,0.0202942,-0.0145569,0.0045700,-0.0292664,-0.0090866,0.0271912,-0.0248566,0.0258484,0.0154572,0.001