INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('FA = −FB. ==== الكهرطيسية ==== تدرس الكهرطيسية التأثيرات التي تحصل بين الجسيمات المشحونة وبين المجالات الكهربائية والمجالات المغناطيسية. ويمكن تقسيم الكهرطيسية إلى؛ كهرباء ساكنة أو «إلكتروستاتيكا» وهي تدرس الشحنات والمجالات الكهربائية الساكنة، و«إلكتروديناميكا» وهو يصف التفاعل بين الشحنات المتحركة والإشعاع الكهرطيسي. ومع أن المعرفة بالكهرباء والمغناطيسية تطورت منذ القدم بشكل منفصل، فقد توصلت النظرية التقليدية للكهرطيسية، خلال القرنين الثامن والتاسع عشر، إلى تحديد العلاقة بين الظاهرتين من خلال قانون لورنتز ومعادلات ماكسويل. فقد تمكن ماكسويل من خلال اشتقاقه لأربعة معادلات تفاضلية من وصف الموجات الكهرطيسية وفهم الطبيعة الموجية للضوء. تهتم الكهرباء الساكنة بدراسة الظواهر المرتبطة بالأجسام المشحونة في حالة السكون، والقوى التي توجهها على بعضها البعض كما يصفها قانون كولوم. ويمكن تحليل سلوك هذه الأجسام من تجاذب أو تنافر من خلال معرفة القطبية والمجال الكهربائي المحيط بها، حيث يكون متناسباً مع مقدار الشحنة والأبعاد التي تفصلها. للكهرباء الساكنة عدة تطبيقات، بدءاً من تحليل الظواهر الكهرطيسية مثل العواصف الرعدية إلى المكثفات التي تستعمل الهندسة الكهربائية. وعندما تتحرك الأجسام المشحونة كهربيًا في مجال كهرطيسي فإنها تنتج مجالاً مغناطيسياً يحيط بها فتختص الديناميكا الكهربائية بوصف الأثار التي تنتج عن ذلك من مغناطيسية وإشعاع كهرطيسي وتحريض كهرطيسي. وتنطوي هذه المواضيع ضمن ما يعرف بالديناميكا الكهربائية التقليدية، حيث تشرح معادلات ماكسويل هذه الظواهر بطريقة جيدة وعامة، وتؤدي هذه النظريات إلى تطبيقات مهمة ومنها المولدات الكهربائية والمحركات الكهربائية. وفي العشرينيات من القرن العشرين، ظهرت نظرية الديناميكا الكهربائية الكمومية وهي تتضمن قوانين ميكانيكا الكم، وتصف التفاعل بين الإشعاع الكهرطيسي والمادة عن طريق تبادل الفوتونات. وهناك صياغة نسبية تقدم تصحيحات لحساب حركة الأجسام التي تسير بسرعات تقارب سرعة الضوء، والتي تظهر بشكل مباشر في معجلات الجسيمات والأنابيب الكهربائية التي تحمل فروق جهد وتيارات كهربائية عالية. تعتبر القوى والظواهر الناجمة عن الكهرطيسية من أكثر الأمور المحسوسة في حياتنا اليومية بعد تلك التي تسببها الجاذبية. فعلى سبيل المثال، الضوء عبارة عن موجة كهرطيسية مرئية تشع من جسيمات مَشحونة ومُعَجلة، وتجد مبادئ الكهرطيسية إلى يومنا هذا العديد من التطبيقات التقنية والطبية، وما الأجهزة الكهربائية مثل الراديو، والمرناة، والهاتف، والقطارات المغناطيسية المعلقة، والألياف البصرية، وأجهزة الليزر إلا بضع أمثلة عن هذه التطبيقات التي صنعت تقدمًا نوعيًا في تاريخ البشرية. ==== الديناميكا الحرارية والميكانيكا الإحصائية ==== تختص الديناميكا الحرارية أو «الثرموديناميك» بدراسة انتقال الطاقة وتحولها في النّظم الفيزيائية، والعلاقة بين الحرارة والشغل والضغط والحجم. تقدم الديناميكا الحرارية التقليدية وصفا عيانيا لهذه الظواهر دون الخوض في التفاصيل مجهرية الكامنة ورائها. فيما تخوض الميكانيكا الإحصائية في تحليل السلوك المعقد للمكونات المجهرية (ذرات، جزيئات) وتستنج منها كَمِيًا الخصائص العيانية للنظام وذلك بواسطة طرق إحصائية. وضعت أسس الديناميكا الحرارية خلال القرنين الثامن والتاسع عشر، وذلك نتيجة للحاجة الملحة في زيادة كفاءة المحركات البخارية. يتأسس فهم ديناميكية الطاقة والمتغيرات في نظام معين على أربعة مبادئ أساسية تسمى قوانين الديناميكا الحرارية. وتعمل معادلات الحالة على تحديد العلاقة بين نوعين من متغيرات العيانية التي تعرف حالة الأنظمة؛ متغيرات الامتداد مثل الكتلة والحجم والحرارة، ومتغيرات الشدّة مثل الكثافة ودرجة الحرارة والضغط والكمون الكيميائي. ويمكن من خلال قياس هذه المتغيرات التعرف إلى حالة التوازن أو التحول التلقائي في النظام. ينص القانون الأول للديناميكا الحرارية على مبدئ حفظ الطاقة، وذلك بأن التغير في الطاقة الداخلية لنظام مغلق وساكن، يساوي كمية الطاقة المتبادلة مع الوسط الخارجي على شكل حرارة أو عمل. فيما ينص القانون الثاني على أن الحرارة لا يمكنها المرور بطريقة تلقائية من جسم ذي درجة حرارة منخفضة إلى آخر ذي درجة حرارة مرتفعة بدون الإتيان بشغل. وذلك يعني أنه من غير الممكن الحصول على شغل دون أن تفقد منه كمية على شكل الحرارة. وتوصل لهذين القانونين الفيزيائي الفرنسي سادي كارنو في بداية القرن التاسع عشر. وفي سنة 1865، أدخل الفيزيائي الألماني رودلف کلاوزیوس دالة الاعتلاج، ومن خلالها يصاغ القانون الثاني على أن «التحول التلقائي في نظام معين لا يمكن أن يتحقق بدون أن ترتفع هذه القيمة فيه وفيما حوله». يُعبر الاعتلاج،', 'Wikipedia Arabic - فيزياء', 'FA = −FB. (part 1)', 'فيزياء', '[0.0191956,0.0095444,0.0134659,0.0128860,0.0315552,0.0723267,-0.0063477,-0.0211334,0.0186920,-0.0201416,0.0098495,0.0020695,-0.0290222,0.0027580,0.0112991,0.0248413,0.0318909,0.0313110,0.0558167,-0.0270081,0.0270233,-0.0608826,-0.0272980,0.0227814,0.0116653,-0.0356750,-0.0420837,-0.0064774,-0.0275421,-0.0139923,0.0184021,-0.0293579,-0.0228119,-0.0386047,-0.0092392,0.0221252,-0.0695801,0.0495911,-0.0181427,0.0067978,0.0047073,-0.0718384,-0.0477295,0.0557861,-0.0604553,-0.0340881,-0.0456848,-0.0168152,0.0789795,-0.0374146,0.0242615,0.0015812,0.0389404,-0.0397949,0.0060539,0.0147629,-0.0173492,0.0317383,0.0479126,-0.0283508,-0.0082016,-0.0444336,0.0163269,-0.0173645,-0.0193939,-0.0030060,-0.0167847,0.0232086,-0.0150681,0.0327148,0.0224915,0.0185394,0.0070534,-0.0140991,-0.0163269,-0.0160675,0.0057259,0.0086212,0.0154953,0.0455627,-0.0325317,-0.0073586,-0.0022812,0.0006809,0.0276184,0.0267639,0.0083313,-0.0039635,-0.0103683,-0.0432434,-0.0307159,0.0110321,0.0046310,-0.0167694,0.0080872,0.0435791,-0.0166016,-0.0219116,0.0190277,-0.0012369,-0.0115204,0.0317383,0.0064621,0.0372314,0.0098343,-0.0192566,-0.0695801,0.0183868,-0.0047455,-0.0298309,0.0599670,-0.0183105,0.0283813,-0.0676880,0.0145416,-0.0277405,-0.0574646,-0.0136261,-0.0580139,-0.0453491,-0.0717773,0.0124207,0.0607605,-0.0158997,0.0109787,-0.0561218,-0.0109711,0.0229492,-0.0213318,-0.0126572,-0.0101166,-0.0267639,-0.0034332,-0.0809937,-0.0164032,0.0162506,0.0370483,-0.0202789,0.0084534,0.0514526,0.0492249,0.0080795,0.0252838,0.0149078,-0.0008664,-0.0198212,0.0103073,0.0234985,0.0252838,0.0052528,0.0134125,0.0128021,0.0064850,-0.0241241,0.0356140,-0.0157928,0.0346375,0.0313721,0.0238037,-0.0371094,0.0023956,-0.0007734,0.0312500,-0.0641479,0.0189362,0.0160675,-0.0378723,0.0229492,-0.0383301,-0.0033970,-0.0511475,-0.0011854,0.0528870,-0.0220490,0.0052719,0.0114822,-0.0032558,-0.0067749,-0.0197296,0.00089