INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('من وجهة نظر عيانية، على عدم إمكانية تسخير كل الطاقة في نظام ما للقيام بعمل ميكانيكي. وتصفها الميكانيكا الإحصائية على أنها قياس لحالة الفوضى للمكونات المجهرية للنظام من ذرات وجزيئات. تتكتسي الديناميكا الحرارية أهمية كبرى في العديد من المجالات؛ في الكيمياء والهندسة الكيميائية وعلم الأحياء وإنتاج الطاقة والتبريد. فعلى سبيل المثال، يمكن للديناميكا الحرارية تفسير الأسباب التي تجعل بعض التفاعلات الكيميائية تحصل من تلقاء نفسها، فيما لا يمكن ذلك للبعض الآخر. === الفيزياء الحديثة === تهتم الفيزياء التقليدية عمومًا بالمادة والطاقة على النطاق الطبيعي للمراقبة، بينما تهتم الكثير من أفرع الفيزياء الحديثة بسلوك المادة والطاقة في ظل الظروف القاسية أو على نطاق كبير جدًا أو صغير جدًا. على سبيل المثال، دراسات الفيزياء الذرية والنووية تهم على نطاق صغير يمكن من خلاله تحديد العناصر الكيميائية. فيزياء الجسيمات الأولية تكون على نطاق أصغر لأنها تهتم بأبسط وحدات المادة؛ يُعرف هذا الفرع من الفيزياء أيضًا باسم فيزياء الطاقة العالية بسبب الطاقات العالية للغاية اللازمة لإنتاج العديد من أنواع الجزيئات في مسرعات الجسيمات. على هذا المقياس، لم تعد المفاهيم العادية المنطقية للفضاء والوقت والمادة والطاقة صالحة. تقدم نظريتان رئيسيتان للفيزياء الحديثة صورة مختلفة عن مفاهيم الفضاء والوقت والمادة عن تلك التي تقدمها الفيزياء التقليدية. تقارب الميكانيكا التقليدية الطبيعة باعتبارها مستمرة، في حين تهتم نظرية الكم بالطبيعة المنفصلة للعديد من الظواهر على المستوى الذري ودون الذري ومع الجوانب التكميلية للجزيئات والأمواج في وصف هذه الظواهر. تهتم نظرية النسبية بوصف الظواهر التي تحدث في إطار مرجعي يتحرك بالنسبة للمراقب؛ تتعلق نظرية النسبية الخاصة بالحركة في غياب حقول الجاذبية ونظرية النسبية العامة بالحركة وعلاقتها بالجاذبية. كلا نظرية الكم ونظرية النسبية تجد تطبيقات في جميع مجالات الفيزياء الحديثة. ==== النسبية ==== نظرية النسبية هي بنية رياضية أكثر عمومية من تلك التي تأسست عليها الميكانيكا التقليدية، وتصف حركة الأجسام بسرعات تقارب سرعة الضوء، أو أنظمة ذات كُتلٍ هائلة، وتشتمل على شقين هما نظرية النسبية الخاصة ونظرية النسبية العامة. اقترح نظرية النسبية الخاصة الفيزيائي الألماني ألبرت أينشتاين، سنة 1905، في ورقة بحثية شهيرة بعنوان «حول الديناميكا الكهربائية للأجسام المتحركة» بناء على المساهمات الهامة لهندريك لورنتس وهنري بوانكاريه. ويتطرق هذا المقال إلى أن نظرية النسبية الخاصة تجد حلا لعدم الاتساق بين معادلات ماكسويل والميكانيكا التقليدية. وتقوم النظرية على مسلمتين هما؛ أن القوانين الفيزيائية لا تتغير بتغير الإطار المرجعي العطالي للنظم،(5) وأن سرعة الضوء في الفراغ هي مقدار ثابت وغير متصل بحركة مصدر الضوء أو بالمشاهد. الدمج بين هاتين المسلمتين يقود إلى افتراض علاقة بين أمرين منفصلين في الميكانيكا التقليدية، وهما المكان والزمان ويجمع بينهما في بنية تسمى الزمكان. إحدى التداعيات الهامة للنسبية الخاصة، والتي تبدو مخالفة للبديهة وإن كانت أثبتتها عدة تجارب، هي انعدام مكان أو زمان مطلق، أي منفصل عن الإطار المرجعي للمشاهد (ومن هنا يأتي مصطلح النسبية). وهذا يعني أن الكتلة والأبعاد والزمن تتغير بتغير سرعة الجسم، وذلك ملائمةً لثبات سرعة الضوء. قد تكون هذه الظواهر غير محسوسة بمجال السرعات في حياتنا اليومية وتبقى بذلك قوانين نيوتن سارية، ولكنها تصير ذات تأثير لا يستهان به عندما ترتفع السرعة وتقارب سرعة الضوء. ومن أهم النتائج الأخرى مبدئ التكافئ بين المادة والطاقة، وهو أمر تعبر عنه بشكل بليغ أحد أشهر المعادلات الفيزيائية:', 'Wikipedia Arabic - فيزياء', 'FA = −FB. (part 2)', 'فيزياء', '[0.0253754,0.0445251,0.0459290,0.0047340,0.0394592,0.0644531,0.0304260,-0.0313110,-0.0092468,-0.0187988,-0.0170746,0.0276642,-0.0516052,-0.0019760,0.0295105,0.0187836,-0.0126343,-0.0118332,0.0468140,0.0074387,0.0102921,-0.0247498,0.0043373,0.0170746,-0.0078583,-0.0473328,0.0178986,0.0233459,0.0249786,-0.0066071,0.0481567,-0.0256348,-0.0302734,-0.0623169,-0.0219421,0.0673218,-0.0487976,-0.0174255,-0.0114746,-0.0267181,-0.0072670,-0.0212860,-0.0571899,-0.0235443,-0.0070801,0.0035381,-0.0301819,-0.0464478,0.0587158,-0.0032406,-0.0058022,0.0285187,0.0251007,0.0012856,-0.0068665,0.0104294,0.0339355,0.0270538,0.0156555,-0.0289612,-0.0007157,-0.0239258,0.0385742,0.0134048,-0.0157471,-0.0020294,0.0015602,-0.0161285,-0.0138321,0.0