INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('E = m c 2 حيث E هي الطاقة، و m هي الكتلة، و c هي سرعة الضوء في الفراغ (2 فوق سرعة الضوء تعني أن الطاقة تتناسب طرديًا مع مربع هذه السرعة). بعبارة أخرى تُنبئنا هذه الصيغة الرياضية أن لكل جسم ذي كتلةٍ طاقةٌ مرتبطة به، والعكس بالعكس. النسبية العامة هي نظرية ذات طابع هندسي، توصل إليها ألبرت أينشتاين بشكل منفرد ونشرها في 15\\1916، وذلك بأنه قام بتوحيد النسبية الخاصة وقانون نيوتن العام للجاذبية. تنص هذه النظرية على أن الجاذبية يمكن وصفها على أنها انحناء في بنية الزمكان تسببه الكتلة أو الطاقة. على الصعيد الرياضي، تتميز النسبية العامة عن غيرها من النظريات الحديثة التي تصف الجاذبية بأنها تستعمل معادلات أينشتاين للمجال لوصف محتوى الزمكان من مادة أو طاقة وأثر ذلك على انحنائه. وتعتمد في ذلك بشكل أساسي على موتر الإجهاد-الطاقة،(6) وهو كائن هندسي يصف عبر مكوناته عدة كميات فيزيائية مثل الكثافة، والتدفق، والطاقة، والزخم، والزمكان. ويمكن القول بطريقة مبسطة، أن موتر الإجهاد-الطاقة هو سبب وجود مجال تثاقلي في زمكان معين وذلك بشكل أعم من ما تفعله الكتلة وحدها في قانون نيوتن الكلاسيكي للجاذبية. من أول المشاهدات التي أكدت على صحة نظرية النسبية العامة، هو تمكنها من احتساب أوج بدارية كوكب عطارد الشاذة، بدقة فشلت في تحقيقها المكانيكا التقليدية. وفي سنة 1919، قام الفلكي الإنجليزي آرثر ستانلي إيدينجتون بمشاهدة انزياح ضوء النجوم القريبة من قرص الشمس خلال الكسوف، ليأكد تنبؤ النسبية العامة بانحناء الضوء تحت تأثير مجال تثاقلي تحدثه أجسام فائقة الكتلة. وفي وقت لاحق بدأت تتراءى العديد من التداعيات لهذه النظرية في علم الكون والتي أكدت بعضها المشاهدات، ولكنها لا تزال موضع جدال، ومنها تنبؤ حلول معادلات أينشتاين بالانفجار العظيم، وتوسع الكون، وطاقة الفراغ، والثقوب السوداء. ==== ميكانيكا الكم ==== تتعامل الميكانيكا الكمومية مع نظم ذات أحجام ذرية أو تحت الذرية؛ مثل الجزيئات والذرات والإلكترونات والبروتونات وغيرها من الجسيمات الأولية. وقد أدت بعض الصعوبات التي واجهت الميكانيكا الكلاسيكية في أواخر القرن التاسع عشر، مثل إشكالية إشعاع الجسم الأسود واستقرار الإلكترونات على مداراتها، إلى التفكير بأن جميع أشكال الطاقة تتنقل على شكل حزم متقطعة غير قابلة للتجزئة، وتسمى كُمُومَات أو «كوانتوم». وقد قام بتشكيل هذا المفهوم، الفيزيائي الألماني ماكس بلانك سنة 1900، وقدم من خلاله ألبرت أينشتاين تفسيرًا للتأثير الكهروضوئي والذي يتبين من خلاله بأن الموجات الكهرطيسية تتصرف في بعض الأحيان بطريقة تشبه تصرف الجسيمات. وضعت مبادئ الميكانيكا الكمومية خلال العشرينات من القرن الماضي، من قبل مجموعة متميزة من الفيزيائيين. في سنة 1924، توصل لويس دي بروليه إلى إدراك أن الأجسام أيضا يمكنها أن تتصرف على أنها موجات، وهو ما يعبر عنه بمثنوية الموجة والجسيم. وقدمت على خلفية ذلك صياغتان رياضيتان مختلفتان وهما؛ الميكانيكا الموجية التي وضعها إرفين شرودنغر وهي تنطوي على استخدام كائن رياضي يسمى دالة الموجة، يصف احتمال وجود جسيم في بقعة ما من الفضاء وميكانيكا المصفوفات التي أنشأها فيرنر هايزنبرغ وماكس بورن، وهي تصف الجسيمات على أنها مصفوفات تتغير مع الزمن. ومع أن هذه الأخيرة لا تشير إلى دالة موجة أو مفاهيم مماثلة، إلا أنها تتوافق مع معادلة شرودنغر ومع الملاحظات التجريبية. وقد شكل مبدأ عدم اليقين الذي صاغه هايزنبرغ في سنة 1927 أحد أهم مبادئ الميكانيكا الكمومية، وهو ينص على محدودية قدرتنا في قياس خاصيتين معينتين لجسيم ما في نفس الوقت وبدرجة عالية من الدّقة. ويضع هذا حدًا لمبدأ الحتمية المطلقة الذي يشير إلى إمكانية التنبؤ بشكل دقيق بحالة نظام انطلاقا من حالته السابقة، حيث أن الظواهر الكمومية لا يمكن تفسيرها إلا بطريقة احتمالية. وقد أدى هذا الأمر إلى جدال علمي كبير دار بين أعظم فيزيائيي القرن العشرين، بما فيهم ألبرت أينشتاين الذي عارض هذا التفسير الاحتمالي بالرغم من إسهاماته الهامة في تأسيس الميكانيكا الكمومية.(7) معادلة شرودنغر والتي هي عبارة عن معادلة تفاضلية جزئية تصف كيفية تغير الحالة الكمية لنظام فيزيائي مع الزمن، وقد صاغها عالم الفيزياء النمساوي إرفين شرودنغر في أواخر عام 1925 ونشرها عام', 'Wikipedia Arabic - فيزياء', 'E = m c 2 (part 1)', 'فيزياء', '[0.0202026,0.0209045,0.0251770,0.0426941,0.0274963,0.0567017,0.0051765,0.0280914,0.0031338,-0.0297394,0.0097809,0.0247040,-0.0438232,-0.0386353,-0.0007000,0.0277405,0.0009775,0.0134888,0.0217133,-0.0481873,-0.0087891,-0.0661621,-0.0350037,0.0298920,-0.0225677,-0.0584412,-