INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('المختلفة التي تحدث في الطبيعة من حيث الظواهر الأبسط. وبالتالي، تهدف الفيزياء إلى ربط الأشياء التي يمكن ملاحظتها بالبشر بالأسباب الجذرية، ثم ربط هذه الأسباب معًا. على سبيل المثال، لاحظ الصينيون القدامى أن بعض الصخور (الحجر الجيري والمغنتيت) تنجذب إلى بعضها البعض بقوة غير مرئية. سمي هذا التأثير فيما بعد بالمغناطيسية، والتي تمت دراستها لأول مرة بدقة في القرن السابع عشر. ولكن حتى قبل اكتشاف الصينيين للمغناطيسية، عرف الإغريق القدماء عن أشياء أخرى مثل الكهرمان، أنه عندما يفرك الفراء من شأنه أن يسبب جاذبية غير مرئية مماثلة بين الاثنين. وقد تمت دراسة هذا الأمر أيضًا لأول مرة في القرن السابع عشر وأصبح يسمى الكهرباء. وهكذا، أصبحت الفيزياء لفهم ملاحظتين للطبيعة من حيث بعض الأسباب الجذرية (الكهرباء والمغناطيسية). ومع ذلك، كشف المزيد من العمل في القرن التاسع عشر أن هاتين القوتين كانتا مجرد جانبين مختلفين لقوة واحدة وهي الكهرطيسية. تستمر عملية «توحيد» القوى هذه اليوم، وتعدالكهرطيسية والقوة النووية الضعيفة الآن جانبين من جوانب التآثر الكهروضعيف. تأمل الفيزياء في إيجاد سبب نهائي (نظرية كل شيء) لسبب الطبيعة كما هي. === مجالات البحث === يمكن تقسيم البحوث المعاصرة في الفيزياء على نطاق واسع إلى الفيزياء النووية وفيزياء الجسيمات؛ فيزياء المواد المكثفة؛ الفيزياء الذرية والجزيئية والبصرية؛ الفيزياء الفلكية والفيزياء التطبيقية. تدعم بعض أقسام الفيزياء أيضًا أبحاث تعليم الفيزياء والتواصل مع الفيزياء. منذ القرن العشرين، أصبحت مجالات الفيزياء الفردية متخصصة بشكل متزايد، واليوم يعمل معظم الفيزيائيين في حقل واحد طوال حياتهم المهنية. أصبحت ظاهرة «العالميون» مثل ألبرت أينشتاين (1879-1955) وليف لانداو (1908-1968)، الذين عملوا في مجالات متعددة من الفيزياء، نادرة جدًا الآن. المجالات الرئيسة للبحوث الفيزيائية، جنبا إلى جنب مع الحقول الفرعية والنظريات والمفاهيم التي توظفها، موضحة في الجدول التالي. ==== الفيزياء النووية وفيزياء الجسيمات ==== فيزياء الجسيمات هي دراسة المكونات الأولية للمادة والطاقة والتفاعلات بينهما. بالإضافة إلى ذلك، يقوم فيزيائي الجسيمات بتصميم وتطوير مسرعات الطاقة العالية، والكاشفات، وبرامج الحاسوب اللازمة لهذا البحث. يُسمى الحقل أيضًا «فيزياء الطاقة العالية» لأن العديد من الجزيئات الأولية لا تحدث بشكل طبيعي ولكن تُنشَأ فقط خلال تصادمات الطاقة العالية لجزيئات أخرى. حاليا، تُوصَف تفاعلات الجسيمات الأولية والحقول بواسطة النموذج القياسي. يفسر النموذج الجزيئات الإثني عشر المعروفة للمادة (الكواركات واللبتونات) التي تتفاعل عبر القوى الأساسية القوية والضعيفة والكهرطيسية. تُوصَف الديناميكيات من حيث جسيمات المادة التي تتبادل بوزونات المقياس (الغلونات، بوزونات W وZ، والفوتونات، على التوالي). يتنبأ النموذج القياسي أيضًا بوجود جسيم يعرف باسم بوزون هيجز. في يوليو 2012، أعلنت سيرن، المختبر الأوروبي لفيزياء الجسيمات، عن اكتشاف جسيم متوافق مع بوزون هيجز، وهو جزء لا يتجزأ من آلية هيجز. الفيزياء النووية هي مجال الفيزياء الذي يدرس مكونات وتفاعلات النواة الذرية. التطبيقات الأكثر شيوعًا للفيزياء النووية هي توليد الطاقة النووية وتكنولوجيا الأسلحة النووية، لكن البحث قدم تطبيقًا في العديد من المجالات، بما في ذلك تلك المتعلقة بالطب النووي وتصوير الرنين المغنطيسي وزرع الأيونات في هندسة المواد والتاريخ بالكربون المشع في الجيولوجيا وعلم الآثار. ==== الفيزياء الذرية والجزيئية والبصرية ==== الفيزياء الذرية والجزيئية والبصرية (AMO) هي دراسة تفاعلات المادة والمادة الضوئية على مقياس الذرات والجزيئات المفردة. تُجمَّع المناطق الثلاثة معًا نظرًا لعلاقاتها المتبادلة، وتشابه الطرق المستخدمة، وترابط مقاييس الطاقة ذات الصلة. جميع المجالات الثلاثة تشمل كلا من العلاجات التقليدية وشبه التقليدية والكمية؛ يمكنهم علاج موضوعهم من وجهة نظر مجهرية (على عكس وجهة نظر مجهرية). تدرس الفيزياء الذرية الأغلفة الإلكترونية للذرات. يركز البحث الحالي على أنشطة التحكم في الكم، والتبريد، ومحاصرة الذرات والأيونات، وديناميات التصادم منخفضة الحرارة وتأثير الارتباط الإلكتروني على الهيكل والديناميات. تتأثر الفيزياء الذرية بالنواة، لكن الظواهر داخل النووية مثل الانشطار والاندماج تعتبر جزءًا من الفيزياء النووية. تركز الفيزياء الجزيئية على الهياكل متعددة الذرات وتفاعلاتها الداخلية والخارجية مع المادة والضوء. تختلف الفيزياء الضوئية عن البصريات من حيث أنها تميل إلى التركيز ليس على التحكم في حقول الضوء التقليدية بواسطة الأجسام المجهرية ولكن على الخصائص الأساسية للمجالات البصرية وتفاعلاتها مع المادة في المجال', 'Wikipedia Arabic - فيزياء', 'تُطبَّق الفيزياء في صناعات مثل الهندسة والطب. (part 2)', 'فيزياء', '[-0.0051804,-0.0097580,0.0056419,0.0216675,0.0377808,0.0174561,0.0312347,0.0039711,-0.0146179,-0.0186157,-0.0089417,0.0152969,-0.0487671,0.0015564,-0.0077400,0.0336304,-0.0145645,0.0267487,0.0568237,-0.0214996,0.0477905,-0.0542603,-0.0390625,0.0089569,-0.0548706,-0.0482483,0.0292053,0.0860596,-0.0118942,0.0385132,0.0757446,-0.0210724,-0.0145493,-0.0321960,-0.0555420,0.0285950,-0.0453796,0.0251007,-0.0207520,0.0005879,0.0127106,-0.0162201,-0.0622559,-0.0181122,0.0174255,0.0432129,-0.0029030,0.0183868,0.0386658,0.0140915,-0.0026207,-0.0061073,0.0499573,-0.0104370,-0.0223389,0.0434875,0.0028229,0.0060501,-0.0068703,-0.0029087,-0.0257874,0.0158844,0.0141373,-0.0144958,-0.0292053,0.0082855,-0.0283661,-0.0095596,0.0176392,0.0203857,0.0452271,0.0075455,-0.0090408,0.0356750,-0.0074463,-0.0174713,0.0374146,-0.0114899,0.0060616,-0.0009351,-0.0093079,-0.0310669,0.0028515,-0.0203705,0.0129547,-0.0078125,0.0017109,-0.0091095,-0.0738525,-0.0205841,-0.0420532,-0.0245819,-0.0437012,-0.0098190,-0.0165558,-0.0214081,-0.0045395,-0.0887451,0.0176697,0.0069542,0.0081558,0.0259094,-0.0367126,0.0321350,0.0150146,-0.0254822,-0.0198212,-0.0609741,-0.0301361,0.0068512,0.0294647,-0.0332947,0.0234222,0.0060806,0.0116730,-0.0122452,-0.0314331,0.0086746,0.0283813,0.0094223,-0.0310364,0.0069389,0.0601501,0.0230560,0.0546570,-0.0439453,-0.0412598,0.0753174,-0.0466919,0.0016499,-0.0079498,-0.0043755,-0.0151901,-0.0381165,-0.0377502,-0.0348206,0.0019779,0.0158844,-0.0026283,0.0572510,-0.0060616,0.0167542,0.0484924,0.0682983,0.0258026,-0.0254669,0.0738525,-0.0181732,0.0150452,0.0517883,0.0313721,-0.0121231,-0.0227966,0.0071640,0.0274200,-0.0008526,0.0187073,0.0252228,-0.0500183,-0.0098724,0.0543213,-0.0269623,-0.0224915,-0.0080414,-0.0158539,-0.0024548,-0.0598145,0.0383606,-0.0212860,0.0049820,-0.0750732,-0.0033073,0.0