INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('المجهري. ==== فيزياء المواد المكثفة ==== فيزياء المواد المكثفة هي مجال الفيزياء الذي يتعامل مع الخواص الفيزيائية العيانية للمادة. على وجه الخصوص، تهتم بالمراحل «المكثفة» التي تظهر كلما كان عدد الجسيمات في النظام كبيرًا للغاية والتفاعلات قوية بينها. الأمثلة الأكثر شيوعًا للمراحل المكثفة هي المواد الصلبة والسوائل، والتي تنشأ عن الترابط عن طريق القوة الكهرطيسية بين الذرات. تشمل المراحل الأكثر تكثيفًا الغريبة الميوعة فائقة ومكثفات بوز-أينشتاين الموجودة في بعض الأنظمة الذرية عند درجة حرارة منخفضة جدًا، ومرحلة التوصيل الفائق التي تظهرها إلكترونات التوصيل في بعض المواد، والمراحل المغناطيسية والمضادة للحرارة المغناطيسية في الدورات الشبكية الذرية. فيزياء المواد المكثفة هي أكبر مجال للفيزياء المعاصرة. تاريخيا، نشأت فيزياء المواد المكثفة من فيزياء الحالة الصلبة، والتي تعتبر الآن واحدة من الحقول الفرعية الرئيسة. من الواضح أن مصطلح فيزياء المواد المكثفة صاغه فيليب أندرسون عندما أعاد تسمية مجموعته البحثية -نظرية الحالة الصلبة سابقًا- في عام 1967. في عام 1978، تم تغيير اسم قسم فيزياء الحالة الصلبة في الجمعية الفيزيائية الأمريكية إلى قسم فيزياء المواد المكثفة. فيزياء المواد المكثفة لها تداخل كبير مع الكيمياء وعلوم المواد وتكنولوجيا النانو والهندسة. ==== الفيزياء الفلكية ==== الفيزياء الفلكية وعلم الفلك هما تطبيق نظريات وأساليب الفيزياء على دراسة البنية النجمية، وتطور النجوم، وأصل النظام الشمسي، والمشاكل المتعلقة بعلم الكونيات. نظرًا لأن الفيزياء الفلكية موضوع واسع، يطبق الفيزيائيون في العادة العديد من تخصصات الفيزياء، بما في ذلك الميكانيكا والكهرطيسية والميكانيكا الإحصائية والديناميكا الحرارية والميكانيكا الكمومية والنسبية والفيزياء النووية والفيزياء الذرية والجزيئية. اكتشاف كارل جانسكي في عام 1931 أن الإشارات الراديوية المنبعثة من الأجرام السماوية قد بدأ علم الفلك الراديوي. في الآونة الأخيرة، تُوسَّع حدود علم الفلك عن طريق استكشاف الفضاء. الاضطرابات والتداخل من الغلاف الجوي للأرض يجعل الرصدات الفضائية ضرورية لعلم الأشعة تحت الحمراء، والأشعة فوق البنفسجية، وغاما، والأشعة السينية. علم الكون الفيزيائي هو دراسة تكوين الكون وتطوره على مقاييسه الأكبر. تلعب نظرية النسبية لألبرت أينشتاين دورًا رئيسيًا في كل النظريات الكونية الحديثة. في أوائل القرن العشرين، اكتشاف هابل أن الكون يتسع، كما هو موضح في مخطط هابل، تفسيرات متنافسة معروفة باسم عالم الحالة المستقرة والانفجار العظيم. أكِّد الانفجار العظيم من خلال نجاح تخليق الانفجار العظيم النووي واكتشاف إشعاع الخلفية الكونية الميكروي في عام 1964. يعتمد نموذج الانفجار العظيم على ركيزتين نظريتين: النسبية العامة لألبرت أينشتاين والمبدأ الكوني. أنشأ علماء الكونيات مؤخرًا نموذج لامبدا-سي دي إم لتطور الكون، والذي يشمل التضخم الكوني والطاقة المظلمة والمادة المظلمة. من المتوقع ظهور العديد من الاحتمالات والاكتشافات من بيانات جديدة من مرصد فيرمي الفضائي لأشعة غاما على مدى العقد المقبل وتنقيح أو توضيح النماذج الحالية للكون بشكل كبير. على وجه الخصوص، إمكانية اكتشاف هائل حول المادة المظلمة ممكنة على مدى السنوات القليلة القادمة. سوف يبحث فيرمي عن دليل على أن المادة المظلمة تتألف من جسيمات التفاعل الضعيف الضخمة، لتكمل تجارب مماثلة مع مصادم الهدرونات الكبير وكاشفات أخرى تحت الأرض. ==== الفيزياء التطبيقية ==== الفيزياء التطبيقية هي تطبيق النظريات الفيزيائية على حل المشكلات. وتعني استخدام المعرفة النظرية لخصائص الأجسام المادية بقصد تحقيق هدف تقني أو عملي معين. وعادة ما يعتبر أيضًا جسرًا أو صلة بين الفيزياء والهندسة. تتميز كلمة «التطبيقية» عن «البحتة» بمجموعة دقيقة من العوامل، مثل دوافع الباحثين وموقفهم وطبيعة العلاقة بالتكنولوجيا أو العلم التي قد تتأثر بالعمل. الفيزياء التطبيقية متجذرة في الحقائق الأساسية والمفاهيم الأساسية للعلوم الفيزيائية، ولكنها تهتم باستخدام المبادئ العلمية في الأجهزة والأنظمة العملية، وفي تطبيق الفيزياء في مجالات العلوم الأخرى. ===== الفيزياء الطبية ===== الفيزياء الطبية (وتسمى أيضًا الفيزياء الطبية الحيوية، الفيزياء الحيوية الطبية، الفيزياء التطبيقية في الطب، تطبيقات الفيزياء في العلوم الطبية، الفيزياء الإشعاعية أو الفيزياء الراديوية بالمستشفيات) هي بشكل عام تطبيق مفاهيم الفيزياء والنظريات وأساليب الطب أو الرعاية الصحية. يمكن العثور على أقسام الفيزياء الطبية في المستشفيات أو الجامعات. في حالة العمل في المستشفى، فإن المصطلح «فيزيائي طبي» هو عنوان مهنة رعاية صحية محددة، وعادة ما يعمل داخل', 'Wikipedia Arabic - فيزياء', 'تُطبَّق الفيزياء في صناعات مثل الهندسة والطب. (part 3)', 'فيزياء', '[-0.0097122,0.0021210,0.0096436,0.0212555,0.0234680,0.0211182,0.0097351,-0.0300751,-0.0297241,0.0420532,-0.0035877,-0.0128403,0.0129623,-0.0228424,0.0181885,0.0369263,0.0061493,0.0182495,0.0304413,-0.0136108,0.0689087,-0.0243683,-0.0076561,-0.0094604,-0.0438538,-0.0921631,0.0312195,0.0446777,-0.0254822,0.0359802,0.0487061,-0.0258179,-0.0138397,-0.0143509,0.0077515,0.0304413,-0.0044708,-0.0048676,0.0077477,0.0245972,0.0250549,0.0099640,-0.0579529,0.0117111,0.0004344,0.0208282,-0.0335083,-0.0047379,0.0095596,0.0040436,-0.0322266,-0.0311737,0.0055275,0.0024071,0.0245819,0.0527954,-0.0090561,-0.0211487,0.0070610,-0.0198669,0.0133209,0.0193024,0.0143661,0.0315247,-0.0515137,0.0159912,-0.0066109,-0.0035744,-0.0164490,-0.0050240,0.0296936,0.0138168,-0.0449219,0.0563660,-0.0042343,-0.0202942,0.0284424,0.0152664,0.0178070,0.0037155,0.0114975,-0.0162048,0.0053215,0.0056648,-0.0315857,0.0049553,-0.0336609,0.0027714,-0.0073128,-0.0543518,-0.0502014,0.0329590,-0.0193024,0.0241852,-0.0076180,0.0009685,-0.0118866,-0.0878906,-0.0154266,0.0340881,0.0267639,0.0087738,-0.0253296,-0.0021744,0.0656738,-0.0299988,-0.0077591,-0.0575867,-0.0399475,0.0302734,-0.0131607,-0.0150146,-0.0057793,0.0223236,0.0421448,0.0119324,-0.0088348,-0.0132599,-0.0117493,-0.0178070,-0.0097275,0.0070953,0.0294189,-0.0099716,0.0045509,-0.0301514,0.0032310,0.0802002,-0.0490417,-0.0273743,0.0100403,0.0125656,-0.0455627,-0.0317688,-0.0095215,-0.0430603,0.0022430,0.0209808,-0.0329285,-0.0213013,0.0130539,-0.0111084,0.0605469,0.0132675,0.0016422,-0.0317993,0.0320740,0.0282745,0.0566406,0.0387878,-0.0326233,0.0490112,-0.0165405,0.0275879,-0.0126953,-0.0126724,0.0376892,0.0383911,-0.0040894,0.0090332,0.0075302,-0.0268555,0.0290527,-0.0008430,-0.0154495,-0.0365906,-0.0221100,0.0416260,-0.0017643,0.0452881,-0.0701904,0.0153809,-0.0109177,0.049408