INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('المستشفى. غالبًا ما يوجد علماء الفيزياء الطبية في تخصصات الرعاية الصحية التالية: الأشعة التشخيصية والتداخلية (المعروفة أيضًا باسم التصوير الطبي) والطب النووي والوقاية من الإشعاع وعلاج الأورام بالإشعاع. أقسام التخصص في الجامعة هي من نوعين. النوع الأول يهتم بإعداد الطلاب لمهنة كفيزيائي طبي في المستشفى ويركز البحث على تحسين ممارسة المهنة. أما النوع الثاني (يسمى بشكل متزايد «فيزياء الطب الحيوي») فيحتوي على نطاق أوسع بكثير وقد يشمل البحث في أي تطبيقات للفيزياء على الطب من دراسة التركيب الجزيئي الحيوي إلى الفحص المجهري والطب النانوي. على سبيل المثال، نظري الفيزياء ريتشارد فاينمان تحدث حول مستقبل الطب النانوي. كتب عن فكرة الاستخدام الطبي للآلات البيولوجية. اقترح فاينمان وألبرت هيبس أن بعض آلات الإصلاح قد يُخفَّض حجمها في يوم من الأيام إلى الحد الذي يصبح من الممكن (كما قال فاينمان) «أن يكون بحجم نانوي». نوقشت الفكرة في مقالة فينمان لعام 1959 «هناك مساحة كافية في الأسفل». ===== تكنولوجيا النانو ===== تقانة الجزيئات متناهية الصغر أو تقانة الصغائر أو تقانة النانو هي العلم الذي يهتم بدراسة معالجة المادة على المقياس الذري والجزيئي. تهتم تقانة النانو بابتكار تقنيات ووسائل جديدة تقاس أبعادها بالنانومتر وهو جزء من الألف من الميكرومتر أي جزء من المليون من الميليمتر. عادة تتعامل تقانة النانو مع قياسات بين 1 إلى 100 نانومتر أي تتعامل مع تجمعات ذرية تتراوح بين خمس ذرات إلى ألف ذرة. وهي أبعاد أقل كثيرا من أبعاد البكتيريا والخلية الحية. حتى الآن لا تختص هذه التقنية بعلم الأحياء بل تهتم بخواص المواد، وتتنوع مجالاتها بشكل واسع من أشباه الموصلات إلى طرق حديثة تماما معتمدة على التجميع الذاتي الجزيئي. هذا التحديد بالقياس يقابله اتساع في طبيعة المواد المستخدمة، فتقانة النانو تتعامل مع أي ظواهر أو بنايات على مستوى النانو الصغير. مثل هذه الظواهر النانوية يمكن أن تتضمن التقييد الكمي التي تؤدي إلى ظواهر كهرطيسية وبصرية جديدة للمادة التي يبلغ حجمها بين حجم الجزيء وحجم المادة الصلبة المرئي. تتضمن الظواهر النانوية أيضا تأثير غيبس طومسون وهو انخفاض درجة انصهار مادة ما عندما يصبح قياسها نانويا، أما عن بنايات النانو فأهمها أنابيب النانو الكربونية. === البحوث الحالية === في فيزياء المواد المكثفة، تتمثل المشكلة النظرية المهمة التي لم تُحل في مشكلة الموصلية الفائقة عالية الحرارة. تهدف العديد من تجارب المواد المكثفة إلى تصنيع الإلكترونيات الدورانية القابلة للتطبيق وأجهزة الحاسوب الكمومية. في فيزياء الجسيمات، بدأت تظهر الأجزاء الأولى من الأدلة التجريبية للفيزياء خارج النموذج القياسي. وفي مقدمة هذه الدلائل تشير إلى أن النيوترونات لها كتلة غير صفرية. يبدو أن هذه النتائج التجريبية قد حلت مشكلة نيوترينو الشمس التي طال أمدها، ولا تزال فيزياء النيوتريونات الضخمة مجالًا للبحث النظري والتجريبي النشط. عثر مصادم الهدرونات الكبير على بوزون هيغز، لكن الأبحاث المستقبلية تهدف إلى إثبات أو دحض التناظر الفائق، الذي يوسع النموذج القياسي لفيزياء الجسيمات. البحث عن طبيعة الألغاز الرئيسية للمادة المظلمة والطاقة المظلمة مستمر أيضًا في الوقت الحالي. المحاولات النظرية لتوحيد ميكانيكا الكم والنسبية العامة في نظرية واحدة لجاذبية الكم، وهو برنامج مستمر منذ أكثر من نصف قرن، لم يُحسَم بعد. المرشحين الرئيسيين الحاليين للحل هم نظرية إم، نظرية الأوتار الفائقة والثقالة الكمومية الحلقية. لم تُفسَّر العديد من الظواهر الفلكية والكونية تفسيراً مرضياً، بما في ذلك أصل الأشعة الكونية ذات الطاقة الفائقة، وعدم تناسق الباريون، وتسارع توسع الكون ومعدلات الدوران الشاذة للمجرات. مع أن التقدم الذي أُحرِز في فيزياء الجسيمات والكم والفيزياء الفلكية كبير، إلا أن العديد من الظواهر اليومية التي تنطوي على التعقيد أو الفوضى أو الاضطراب لا تزال غير مفهومة جيدًا. المشاكل المعقدة التي تبدو وكأنها يمكن حلها عن طريق تطبيق ذكي للديناميات والميكانيكا تبقى دون حل؛ ومن الأمثلة على ذلك تشكيل الكتل الرملية والعقد في المياه المتدفقة وشكل قطرات الماء وآليات كوارث التوتر السطحي والفرز الذاتي في مجموعات متجانسة غير متجانسة. حظيت هذه الظواهر المعقدة باهتمام متزايد منذ سبعينيات القرن الماضي لعدة أسباب، بما في ذلك توافر الأساليب الرياضية الحديثة', 'Wikipedia Arabic - فيزياء', 'تُطبَّق الفيزياء في صناعات مثل الهندسة والطب. (part 4)', 'فيزياء', '[0.0006766,0.0493469,0.0550232,0.0182343,0.0071068,0.0323486,0.0067902,0.0035400,-0.0075912,-0.0284882,0.0